#include <errno.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

#include "io/io.h"
#include "version.h"  // generated by the Makefile: OPTIMICE_VERSION

// The results file: opened by output_open after loading, closed by output_close. Rows are written
// by whichever thread holds the batch's print lock, in job order, so one writer at a time and the
// same file for any thread count. NULL when --output is off
static FILE* out;
static char* out_path;

static noreturn void die_errno(const char* what, const char* path) {
  die("%s '%s': %s", what, path, strerror(errno));
}

// --- Paths ---

static int is_dir(const char* path) {
  struct stat st;
  return stat(path, &st) == 0 && S_ISDIR(st.st_mode);
}

// mkdir -p for every directory in `path` up to its last '/', so a file's parents, or a directory
// given with a trailing slash, exist afterwards. Components that already exist are fine
static void make_parents(const char* path) {
  char* p = xmalloc(strlen(path) + 1);
  strcpy(p, path);
  for (char* s = strchr(p + 1, '/'); s; s = strchr(s + 1, '/')) {
    *s = '\0';
    if (mkdir(p, 0777) != 0 && errno != EEXIST) die_errno("cannot create directory", p);
    *s = '/';
  }
  free(p);
}

// The config file's name without its directory and a trailing ".toml"
static char* config_stem(const char* config_path) {
  const char* base = strrchr(config_path, '/');
  base             = base ? base + 1 : config_path;
  size_t n         = strlen(base);
  if (n > 5 && strcmp(base + n - 5, ".toml") == 0) n -= 5;
  char* stem = xmalloc(n + 1);
  memcpy(stem, base, n);
  stem[n] = '\0';
  return stem;
}

// Creates `<dir><stem>-<YYYYMMDD-HHMMSS>.csv` exclusively ("wx"), so it never replaces anything:
// if the name exists (same config, same second), tries -2, -3, ... up to -99
// `dir` is "" for the current directory, or ends in '/'
static FILE* open_generated(const char* dir, const char* config_path, const struct tm* now) {
  char* stem = config_stem(config_path);
  char  stamp[32];
  strftime(stamp, sizeof(stamp), "%Y%m%d-%H%M%S", now);

  size_t cap = strlen(dir) + strlen(stem) + strlen(stamp) + 16;
  out_path   = xmalloc(cap);
  FILE* f    = NULL;
  for (int k = 1; k <= 99 && !f; k++) {
    if (k == 1) snprintf(out_path, cap, "%s%s-%s.csv", dir, stem, stamp);
    else snprintf(out_path, cap, "%s%s-%s-%d.csv", dir, stem, stamp, k);
    f = fopen(out_path, "wx");
    if (!f && errno != EEXIST) die_errno("cannot create", out_path);
  }
  if (!f) die("cannot create '%s': names up to -99 are already taken", out_path);
  free(stem);
  return f;
}

// --- Config checksum ---

// POSIX cksum: CRC-32 over the file's bytes, then over its length in as few bytes as it takes,
// least significant first; the result is complemented
// Matches `cksum FILE`, so anyone can check the header against a TOML without optimiCe

static uint32_t crc_byte(uint32_t crc, unsigned char b) {
  crc ^= (uint32_t) b << 24;
  for (int i = 0; i < 8; i++) crc = crc & 0x80000000u ? (crc << 1) ^ 0x04C11DB7u : crc << 1;
  return crc;
}

static void cksum_file(const char* path, uint32_t* crc_out, uint64_t* len_out) {
  FILE* f = fopen(path, "rb");
  if (!f) die_errno("cannot read", path);
  uint32_t crc = 0;
  uint64_t len = 0;
  int      c;
  while ((c = getc(f)) != EOF) {
    crc = crc_byte(crc, (unsigned char) c);
    len++;
  }
  if (ferror(f)) die_errno("cannot read", path);
  fclose(f);
  for (uint64_t n = len; n; n >>= 8) crc = crc_byte(crc, (unsigned char) (n & 0xff));
  *crc_out = ~crc;
  *len_out = len;
}

// --- Open / close ---

void output_open(const Batch* batch, const char* config_path, const char* arg) {
  if (arg && !*arg) die_with_hint("--output was given an empty path");
  time_t    t = time(NULL);
  struct tm now;
  localtime_r(&t, &now);

  // A trailing slash means a directory, created if needed; a path that's already a directory
  // means the same without the slash; anything else is a file, overwritten if it exists
  if (!arg) {
    out = open_generated("", config_path, &now);
  } else if (arg[strlen(arg) - 1] == '/' || is_dir(arg)) {
    size_t n   = strlen(arg);
    char*  dir = xmalloc(n + 2);
    snprintf(dir, n + 2, "%s%s", arg, arg[n - 1] == '/' ? "" : "/");
    make_parents(dir);
    out = open_generated(dir, config_path, &now);
    free(dir);
  } else {
    make_parents(arg);
    out_path = xmalloc(strlen(arg) + 1);
    strcpy(out_path, arg);
    out = fopen(out_path, "w");
    if (!out) die_errno("cannot write", out_path);
  }
  fprintf(stderr, "Output: %s\n", out_path);

  uint32_t crc;
  uint64_t len;
  cksum_file(config_path, &crc, &len);
  char date[64];
  strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S %z", &now);

  fprintf(out, "# optimice %s\n", OPTIMICE_VERSION);
  fprintf(out, "# config: %s (cksum %u %llu)\n", config_path, crc, (unsigned long long) len);
  fprintf(out, "# date: %s\n", date);
  fprintf(out, "# jobs: %d\n", batch_jobs(batch));
  fprintf(out, "run,replicate,seed,fitness,iterations,evaluations,stop,position\n");
  output_flush();
}

// One row per job
// No field contains a comma or a quote (labels are <algorithm>-<n>, the rest numbers and fixed
// words), so nothing needs quoting. The position's coordinates are separated by spaces, which
// keeps it one column whatever n_dims is
// Flushed per row, so a batch that dies or is killed leaves every finished row on disk
void output_row(const char* label, int replicate, uint32_t seed, int n_dims, const RunResult* res) {
  if (!out) return;
  static const char* const stop_names[] = {
      [STOP_NONE] = "none", [STOP_TARGET] = "target", [STOP_STAGNATION] = "stagnation"};

  char num[FMT_EXACT_LEN];
  fmt_exact(num, res->fitness);
  fprintf(out, "%s,%d,0x%08x,%s,%d,%" PRIu64 ",%s,", label, replicate, seed, num,
          res->stop.iterations, res->evaluations, stop_names[res->stop.reason]);
  for (int d = 0; d < n_dims; d++) {
    fmt_exact(num, res->pos[d]);
    fprintf(out, "%s%s", d ? " " : "", num);
  }
  fputc('\n', out);
  output_flush();
}

void output_flush(void) {
  if (!out) return;
  if (fflush(out) != 0 || ferror(out)) die_errno("cannot write", out_path);
}

void output_close(void) {
  if (!out) return;
  output_flush();
  if (fclose(out) != 0) die_errno("cannot write", out_path);
  out = NULL;
  free(out_path);
}
